 data['modules'].append(dict(id='world',name='世界教会史',range=[452,1648],heading=['穿过千年','看见众教会。'],lead='从中世纪到宗教改革，也从欧洲望向世界。',eyebrow='THE WORLD CHURCH · 452—1648',footer='WORLD CHURCH · 452—1648'))
 places={
 'reims':['兰斯','Reims','今法国兰斯',4.03,49.26,'高卢—法兰克','克洛维受洗传统的城市背景。传统纪年与现代研究存在分歧；城市位置不代表已确定洗礼现场的全部建筑细节。'],
 'monte-cassino':['卡西诺山','Monte Cassino','今意大利卡西诺附近',13.81,41.49,'意大利修道网络','本笃传统的重要修院所在地。会规的编写与接受是长期过程，不能把欧洲所有修院视为从同一年起采用同一种制度。'],
 'iona':['爱奥那','Iona','今英国苏格兰西海岸爱奥那岛',-6.42,56.33,'爱尔兰海—苏格兰','哥伦巴修道团体的重要基地，海路连接爱尔兰、不列颠与更远地区；地图只标岛屿，不复原逐日航线。'],
 'canterbury':['坎特伯雷','Canterbury','今英国英格兰坎特伯雷',1.08,51.28,'不列颠','奥古斯丁传教团与肯特王国的联系中心。不列颠此前已有基督教传统，597年不是岛上第一次出现基督徒。'],
 'dongola':['栋古拉地区','Old Dongola','今苏丹古栋古拉遗址',30.44,18.22,'尼罗河—努比亚','努比亚诸国的教会、壁画与礼仪传统延续数百年。这里是区域参照，不把诺巴提亚、马库里亚与阿洛迪亚合为同一国家。'],
 'kerala':['马拉巴尔海岸','Malabar / Kerala','今印度喀拉拉海岸区域代表点',76.27,9.97,'印度洋','海贸与叙利亚语礼仪联系的重要地区。多马使徒传统、六世纪旅行文本与近世教会会议必须分别标注证据性质。'],
 'xian':['长安','Chang’an / Xi’an','今中国陕西西安',108.94,34.34,'中国—丝绸之路','唐代景教碑记述东叙利亚传统在华的活动。碑文的立石年代、所追述的来华年代和近世出土时间不可混同。'],
 'moravia':['大摩拉维亚地区','Great Moravia','今捷克东南与斯洛伐克西部的区域代表点',17.0,48.9,'斯拉夫世界','西里尔与美多迪乌的语言和礼仪事业涉及多处宫廷与教会；区域代表点不宣称已确定使团全部活动中心。'],
 'preslav':['普雷斯拉夫地区','Preslav / Bulgaria','今保加利亚普雷斯拉夫一带',26.81,43.16,'保加利亚','保加利亚王室归信及斯拉夫语书写网络的区域背景。865年王室受洗与后来普雷斯拉夫文化中心的发展不是同一事件。'],
 'cluny':['克吕尼','Cluny','今法国勃艮第克吕尼',4.66,46.43,'西欧修道网络','910年的创建文书说明修院财产、保护与院长选举安排；克吕尼网络随后数世纪逐渐扩大。'],
 'kyiv':['基辅','Kyiv','今乌克兰基辅',30.52,50.45,'罗斯世界','罗斯受洗记忆的重要城市。中世纪罗斯与今天多个国家的历史有关，不能由988年事件推导现代政治归属。'],
 'clermont':['克莱蒙','Clermont','今法国克莱蒙费朗',3.08,45.78,'法国中部','1095年乌尔班二世号召的城市背景。存世演说版本写作时间与作者立场不同，不能合并为逐字现场录音。'],
 'mainz':['美因茨','Mainz','今德国美因茨',8.27,50.00,'莱茵河流域','1096年犹太群体遭受袭击，也是十五世纪活字印刷的重要城市。地图以不同时代纪事区分城市角色。'],
 'worms':['沃尔姆斯','Worms','今德国沃尔姆斯',8.36,49.63,'神圣罗马帝国','1122年的政教妥协与1521年的帝国议会相隔近四百年，不能把两次围绕权威的争论当成同一事件。'],
 'bingen':['宾根地区','Bingen / Rupertsberg','今德国宾根及莱茵河附近',7.9,49.97,'莱茵河修道网络','希尔德加德的写作、修道生活和书信联系的区域背景；异象文本、医学著述与音乐应按不同文类理解。'],
 'assisi':['阿西西','Assisi','今意大利翁布里亚阿西西',12.62,43.07,'意大利城市与托钵修会','方济各及其群体活动的重要城市。会规、遗嘱与后世传记提供不同证据，不把晚出的传奇全部回填成生平事实。'],
 'paris':['巴黎','Paris','今法国巴黎',2.35,48.86,'法国—大学网络','大学、经院讨论、王权和宗教冲突交织的城市。十三世纪神学教学与十六世纪屠杀分别属于不同政治和教会情境。'],
 'karakorum':['哈剌和林','Karakorum','今蒙古国鄂尔浑河谷古城区域',102.82,47.20,'蒙古帝国','多宗教宫廷与欧亚旅行记的节点。鲁布鲁克的报告保存观察，也带着拉丁修士的判断，不能替代当地各群体自己的声音。'],
 'tabriz':['大不里士','Tabriz','今伊朗大不里士',46.29,38.08,'伊儿汗国—东叙利亚网络','拉班扫马旅途和蒙古外交联系的区域背景。此城用作出使欧洲的出发区域定位，不表示整个使团只从单一宫殿出发。'],
 'avignon':['阿维尼翁','Avignon','今法国阿维尼翁',4.81,43.95,'罗讷河流域','十四世纪教廷驻地。教廷居留、政治管辖和后来的多位教皇竞争应按时间分别理解。'],
 'prague':['布拉格','Prague','今捷克布拉格',14.42,50.08,'波希米亚','胡斯改革、大学争论和1618年政治危机的不同背景。捷克宗教生活长期多样，不等同于单一宗派阵营。'],
 'constance':['康斯坦茨','Constance / Konstanz','今德国康斯坦茨',9.17,47.66,'博登湖地区','1414—1418年大公会议所在地，既涉及结束拉丁教会多教皇竞争，也涉及胡斯审判等不同议程。'],
 'florence':['佛罗伦萨','Florence','今意大利佛罗伦萨',11.26,43.77,'意大利','1439年合一文书的城市背景。代表签署与各地教会实际接受不可混为一谈，后续争议仍需单独追踪。'],
 'mbanza-kongo':['姆班扎刚果','Mbanza Kongo','今安哥拉北部姆班扎刚果',14.24,-6.27,'中部非洲—大西洋','刚果王国都城，又名圣萨尔瓦多。王室书信、在地艺术与跨大西洋交往呈现非洲基督徒的主动选择及其面对的奴隶贸易压力。'],
 'basel':['巴塞尔','Basel','今瑞士巴塞尔',7.59,47.56,'莱茵河—印刷网络','伊拉斯谟新约出版及人文主义学术的城市背景。印刷把校勘、译文、神学争论和出版市场连接起来。'],
 'wittenberg':['维滕贝格','Wittenberg','今德国路德城维滕贝格',12.65,51.87,'萨克森','路德教学、出版与改革的中心之一。1517年的文献传播与后来不同教会制度成形不是同一天完成的过程。'],
 'zurich':['苏黎世','Zürich','今瑞士苏黎世',8.54,47.38,'瑞士城市共和国','慈运理改革与早期再洗礼群体活动的城市；城市议会的宗教政策并不能代表所有居民一致赞同。'],
 'schleitheim':['施莱特海姆','Schleitheim','今瑞士沙夫豪森州施莱特海姆',8.48,47.75,'瑞士—德意志边境','1527年弟兄会信仰文书的关联地点。文书代表特定群体的立场，不能用来概括所有被称作再洗礼派的人。'],
 'augsburg':['奥格斯堡','Augsburg','今德国奥格斯堡',10.90,48.37,'神圣罗马帝国','1530年信仰陈述与1555年宗教和约的重要地点；教义文本、帝国法律和个体信仰自由不能直接画等号。'],
 'london':['伦敦','London','今英国伦敦',-0.13,51.51,'英格兰','王权、议会、印刷与多次宗教政策转变的中心。十六世纪英格兰改革包括断续、反转与不同群体间的冲突。'],
 'geneva':['日内瓦','Geneva','今瑞士日内瓦',6.14,46.20,'改革宗城市网络','加尔文的教学与教会治理的重要背景；移民、城市议会和教牧机构之间既合作，也存在权力与纪律争议。'],
 'trent':['特伦托','Trent / Trento','今意大利特伦托',11.12,46.07,'阿尔卑斯南麓','1545—1563年的会议主要会址，其间多次中断并曾迁至博洛尼亚，不能画成连续十八年的单一会期。'],
 'goa':['果阿','Goa','今印度果阿旧城一带',73.91,15.50,'印度洋—葡萄牙网络','耶稣会、学校和印刷的重要据点，同时涉及葡萄牙殖民政权与宗教强制。不能把此地传教当作印度基督教的起点。'],
 'mexico':['墨西哥城','Mexico City','今墨西哥首都地区',-99.13,19.43,'中美洲—新西班牙','西班牙征服后的城市重建、修会传教、原住民语言文本和强制劳动相互交织。地图保留原住民群体的处境与能动性。'],
 'kagoshima':['鹿儿岛','Kagoshima','今日本九州鹿儿岛',130.56,31.60,'日本—东亚海域','1549年沙勿略抵达的重要地点。日本信徒、翻译者、地方领主与海外传教士共同参与后续发展。'],
 'nagasaki':['长崎','Nagasaki','今日本九州长崎',129.88,32.75,'日本—东亚海域','海贸、传教与迫害的城市背景。1597年处刑、1614年禁教和后来的潜伏信仰需区分年代，不能把近代复兴倒置到此时。'],
 'edinburgh':['爱丁堡','Edinburgh','今英国苏格兰爱丁堡',-3.19,55.95,'苏格兰','1560年议会与信仰文书的政治背景。王室、贵族、城市与改革者的诉求并非始终一致，改革没有消除所有宗教冲突。'],
 'avila':['阿维拉','Ávila','今西班牙阿维拉',-4.70,40.66,'伊比利亚','德肋撒改革加尔默罗修院的重要地点。女性写作、祈祷实践、教会审批与修院治理构成复杂互动。'],
 'nantes':['南特','Nantes','今法国南特',-1.55,47.22,'法国','1598年敕令的关联地点，给予胡格诺群体有限保障。保障有地域、法律和执行条件，并非现代完全宗教平等。'],
 'beijing':['北京','Beijing','今中国北京',116.41,39.90,'明代中国','利玛窦及中国合作者参与的知识与信仰交流中心。1601年是抵京节点，不是基督教初次进入中国。'],
 'dordrecht':['多特','Dordrecht','今荷兰多德雷赫特',4.67,51.81,'尼德兰','1618—1619年会议所在地，争论与荷兰政治局势相互影响；改革宗内部也存在不同意见与被排除的声音。'],
 'lalibela':['拉利贝拉','Lalibela','今埃塞俄比亚拉利贝拉',39.05,12.03,'埃塞俄比亚高地','岩凿教堂延续埃塞俄比亚自身礼仪与朝圣传统。建筑年代需要按遗址研究区分，不能仅依单一传奇排定全部工程。'],
 'gondar':['贡德尔地区','Gondar / Ethiopian Highlands','今埃塞俄比亚高地的区域代表点',37.47,12.60,'埃塞俄比亚','十七世纪王室宗教政策与耶稣会冲突的区域定位。1632年的宫廷在多个地点移动，不把后来都城的位置当作退位的精确会址。'],
 'valladolid':['巴利亚多利德','Valladolid','今西班牙巴利亚多利德',-4.73,41.65,'伊比利亚—美洲联系','1550—1551年讨论殖民征服与原住民处境的辩论地点。讨论涉及美洲，却不能把会场直接放在墨西哥城；存世文献也不构成完整逐字会议记录。'],
 'damascus':['大马士革','Damascus','今叙利亚大马士革',36.29,33.51,'叙利亚','大马士革的约翰出身于此，后来的修道和写作与巴勒斯坦修院有关。城市代表其历史区域，不将所有圣像辩护文本都定位在这里的同一建筑。'],
 'munster':['明斯特','Münster','今德国明斯特',7.63,51.96,'威斯特伐利亚','1648年和约的谈判城市之一；同时也在奥斯纳布吕克谈判。地图不以一个点替代所有条约和参与者。']}
