 events=[]
 def add(year,place,title,category,people,source,summary,p1,p2,p3,certainty='历史文献',label=None,connections=None):
  phase=next(r for r in phases if r[3][0]<=year<=r[3][1]);ref,url=sources[source]
  evidence='机构研究 / 后世回顾' if source in {'cyril','schism','hildegard','gutenberg','kongo','erasmus','supremacy','jesuit','nagasaki','nantes','diamper','ethiopia','mexican-monasteries'} else '历史文献 / 旧译'
  events.append(dict(sourceType=evidence,id=f'world-{len(events)+1:03}',module='world',route=phase[0],year=year,place=place,title=title,category=category,people=people.split('、'),ref=ref,primarySource=dict(label=ref,url=url),summary=summary,narrative=[p1,p2,p3],certainty=certainty,yearLabel=label or f'公元 {year} 年',arrivalMode='context',waypoints=[],connections=connections or [],references=[]))
 add(494,'rome','两种权威：格拉修一世致皇帝书','制度与权威','格拉修一世、阿纳斯塔修斯','gelasius','罗马主教以书信讨论祭司职分和皇帝权力，留下中世纪政教关系的重要文本。','格拉修一世写给皇帝的书信区分祭司的神圣职分与君王的世俗权力，同时强调在圣事问题上皇帝也需听从教会。这反映罗马与君士坦丁堡之间具体的争论。','后人反复引用这一文本讨论教会和国家，但信中的两种权威并非现代宪政意义的政教分离。主教对优先地位的主张，也不代表各地教会已经接受同一种权力结构。','本条以494年书信为节点，接续451年之后的制度史。阅读时应区分作者规范性的要求、对手的立场和当时实际执行情况，不能将文本当作全欧洲统一生效的宪法。')
 add(496,'reims','克洛维受洗与法兰克王权','归信与社会','克洛维、克洛蒂尔德、雷米','clovis','法兰克王室归信尼西亚传统，改变王权与高卢主教之间的关系。','都尔的格列高利等后来的作者把克洛维的受洗与王后的影响、战争记忆及兰斯主教联系起来。王室归信使法兰克统治者与当地尼西亚传统主教形成新的合作条件。','这与一些采用其他基督论传统的日耳曼王国形成差异，却不能用一个洗礼仪式代表全部法兰克人同时改变信仰。地方习俗、贵族利益与主教网络继续长期互动。','496年是传统纪年，研究也提出较晚年代，本站用传统年作浏览落点。记述中的神迹和戏剧化场景属于作者表达的信仰意义，不能自动视为独立证实的现场细节。',certainty='传统纪年 · 日期有争议',label='传统公元496年 · 亦有较晚年代说')
 add(530,'monte-cassino','本笃会规与共同生活','修道与敬虔','努尔西亚的本笃','benedict','以祈祷、劳动、阅读和院长治理组织共同生活的会规，逐渐影响拉丁西方。','《本笃会规》规定修士如何祈祷、工作、接待客旅、使用财物和处理群体纪律。它借鉴更早的修道材料，呈现一种强调稳定共同生活及循序训练的组织方式。','这套规范日后在西欧获得广泛影响，但最初并非所有修院都采用它。修道院既是敬虔生活的场所，也与土地、手抄本、教育和地方社会发生密切联系。','会规通常约定于六世纪前半叶，本站取530年为阅读落点。不要把后来本笃会的联合组织形式直接投射到作者生前，也不能把欧洲知识的保存全部归功于单一种修院传统。',certainty='成书约年',label='约公元530年')
 add(537,'constantinople','圣索菲亚：礼仪与帝国建筑','礼仪与文化','查士丁尼、狄奥多拉、普罗柯比','sophia','新建圣索菲亚大教堂体现皇帝资助、工程技术和首都礼仪的结合。','查士丁尼统治时期重建的圣索菲亚于537年举行奉献礼。建筑的巨大穹顶、采光和内部空间，使帝国首都的礼仪生活获得新的舞台，也展示皇帝投入的财力与组织能力。','普罗柯比的建筑颂述赞美皇帝与工程，具有鲜明的赞助与修辞背景。建筑不仅表达信仰，也与城市骚乱后的重建、政治秩序和皇帝形象相连。','本条定位到城市与建筑群，不把现存每一部分都说成537年的原物。穹顶后来受损重建，建筑经历多个政权和用途变化，应把不同历史层次分别理解。')
 add(550,'kerala','印度洋沿岸的叙利亚语教会','跨洲传播','科斯马斯、印度基督徒','cosmas','六世纪旅行文本提到印度及附近海域的基督徒，显示罗马帝国外的贸易和教会联系。','科斯马斯在《基督教地志》中谈到印度、海岛和波斯联系中的基督徒与教牧人员。无论作者的宇宙观如何，这些片段都为研究印度洋海贸中的教会网络提供了材料。','当地基督徒与叙利亚语礼仪传统的联系，不能简化为欧洲近世船队到来之后才出现。商人、翻译者和地方群体参与了跨海联系，宗教交流并非只有帝国征服一种方式。','本站取约550年为文本见证的落点。多马使徒来印的传统属于更早起源记忆，不能仅凭六世纪记述证明其全部细节；区域点位也不代表已确认每一座古代聚会所。',certainty='文本见证 · 约年',label='约公元550年')
 add(553,'constantinople','第二次君士坦丁堡会议','会议与教义','查士丁尼、维吉利乌斯','councils','围绕三章问题的谴责与迦克墩解释，加深帝国教会内部的张力。','553年的会议在查士丁尼统治下召开，讨论所谓三章问题，谴责若干与早先基督论争议相关的著作和人物。皇帝试图在维护迦克墩框架的同时处理非迦克墩方面的反对。','罗马主教维吉利乌斯与皇帝及会议之间经历复杂交涉，西方部分地区也出现长期抵制。会议说明制度上的共同归属并不能消除对文本、人物和权威的不同判断。','后来的不同教会传统对这一会议的地位并不一致。不要把谴责的对象直接等同为今天某一教会全体，也不应把帝国期望达成的合一写成当年已经实际完成的结果。')
 add(563,'iona','爱奥那修院与海上网络','修道与敬虔','哥伦巴、阿多姆南','iona','哥伦巴及同伴在爱奥那建立修道基地，联系爱尔兰与不列颠的不同群体。','哥伦巴由爱尔兰来到爱奥那的传统，通常以563年为节点。岛上的修道团体通过海路与周边王国和教会互动，抄写、教导与传教活动成为其后续影响的重要部分。','阿多姆南的传记写作晚于哥伦巴本人，保存修院记忆，也通过神迹叙述呈现圣者形象。阅读它可以认识团体如何理解自己的使命，而不必将所有片段视为同等可靠的行程记录。','本条不把不列颠和爱尔兰写成此前没有基督徒的空白地带。各地礼仪、历法与组织方式存在差异，后来围绕复活节日期的争论也不能简化成现代民族教会之间的对抗。',certainty='修院传统与后期传记')
 add(580,'dongola','努比亚诸国的基督教化','非洲教会','以弗所的约翰、努比亚信徒','nubia','六世纪尼罗河中游的不同王国发展基督教礼仪与教会组织，形成长期延续的非洲传统。','以弗所的约翰等文献记述帝国使者、传教人员与努比亚统治者的交涉。诺巴提亚、马库里亚和阿洛迪亚的归信并非同一次行动，年代与教会联系也有差别。','当地文字、教堂遗址和壁画显示这些群体并非欧洲教会的短暂附录。它们在埃及与内陆非洲之间形成自己的政治、艺术与礼仪生活，延续到中世纪更晚阶段。','约580年仅作为六世纪中后期发展阶段的落点，不是三国统一受洗日。用语涉及不同基督论传统时，应区分古代争论的标签与今日科普特等教会对自身信仰的表述。',certainty='多阶段过程 · 约年',label='六世纪中后期 · 浏览落点580年')
 add(597,'canterbury','坎特伯雷使团与英格兰教会','跨域传播','坎特伯雷的奥古斯丁、格列高利一世、埃塞尔伯特','bede','由罗马派出的使团在肯特活动，与当地王室及既存基督徒网络相遇。','格列高利一世派出的奥古斯丁使团抵达肯特，通常以597年为节点。王室婚姻、法兰克联系和肯特政治局势，为使团开展活动提供了条件，坎特伯雷逐渐成为重要中心。','比德后来将这一过程写入英格兰教会历史。其记述保存书信和传统，同时用神学目的组织故事，显示罗马、地方统治者与修道网络之间复杂的合作。','597年不是基督教首次进入不列颠。罗马时期及凯尔特地区已有群体，后来英格兰教会的整合也经历历法、礼仪与权威上的谈判，不能概括成一次和平而整齐的替代。')
 add(635,'xian','阿罗本来华的碑文记忆','跨洲传播','阿罗本、唐太宗、景净','xian','781年的景教碑追述阿罗本于635年来到长安，留下唐代东西交流的重要证据。','景教碑在781年立石，追述阿罗本于唐太宗时期来到长安、翻译教义并获得活动空间。它用汉文与叙利亚文相关信息表达一支东叙利亚传统在唐代的存在。','这段历史联系西亚、中亚与中国，并非欧洲近世传教的前奏复制品。碑文采用当时汉语宗教与政治语汇，反映翻译、在地理解和争取朝廷认可的努力。','635年是碑文所追述的来华纪年，不能称为保存至今的635年现场记录。景教与现代各教会之间的延续关系也不能只靠名称推定，本站不把碑上赞颂当作全唐人口信仰统计。',certainty='后立碑文追述')
 add(638,'jerusalem','穆斯林统治下的耶路撒冷','宗教与政治','索弗罗尼乌斯、欧麦尔','omar','城市统治变化开启新的制度环境，基督徒群体在不同限制与协商之中继续生活。','七世纪阿拉伯征服改变耶路撒冷及周边的政治环境。主教、修士和当地信徒在新的统治关系下继续礼仪与朝圣生活，不同地区和时期的税赋、保护及限制各有差异。','后世以欧麦尔名义流传的盟约经常被用于说明非穆斯林地位，但其传本和条款具有复杂形成史。应把法律理想、地方协商和实际生活分别考察。','本图以通常采用的638年作为统治变化节点，不把晚出的盟约逐字视作当年签署原件。也不把新的政权色块解释为全城居民即时归信伊斯兰或基督教活动突然终止。',certainty='统治转折 · 盟约传本较晚')
 add(681,'constantinople','第六次大公会议与意志争论','会议与教义','君士坦丁四世、认信者马克西姆','councils','680—681年的会议讨论基督的意志与行动，回应长期的帝国教会争论。','君士坦丁堡的会议在680—681年讨论基督具有怎样的意志与行动，拒绝把一意志论作为帝国教会妥协方案。马克西姆等较早反对者的论述，是理解争议的重要背景。','争论既涉及如何表达基督的完整人性与神性，也涉及皇帝、宗主教和罗马主教的权威。曾经得到政治支持的公式，后来又可能成为谴责对象，显示教义与政策并非简单同步。','本站取681年会议结束为节点。大公会议的编号来自接受这些会议的特定传统，不能暗示所有东方教会都采用相同名单，也不以现代简化口号替代古代术语的具体含义。')
 add(730,'damascus','圣像争论与约翰的辩护','礼仪与文化','大马士革的约翰、利奥三世','icons','圣像的使用、敬礼与禁令引起激烈争辩，作者从道成肉身出发为图像辩护。','八世纪拜占庭的圣像争论牵动皇帝、主教、修士与普通信徒。大马士革的约翰在帝国直接控制之外写作，区分敬礼和对上帝的崇拜，并将图像讨论与道成肉身相联系。','争论不只是艺术风格之争，还涉及教导、圣物、礼仪以及谁有权规定公共信仰表达。不同地区执行禁令的程度和材料保存状况，也使事件重建存在困难。','约730年是争论阶段的浏览落点，不表示全部论文写于同一年。地图以大马士革表示作者的出身与叙利亚区域背景，不把图钉当作确切写作书房；其修道和写作也与巴勒斯坦的修院有关。',certainty='论争阶段 · 约年',label='约公元730年')
 add(781,'xian','景教碑：汉文与叙利亚文的相遇','文献与翻译','景净、伊斯','xian','在长安立石的景教碑，把信仰陈述、来华记忆与唐代政治叙事连接起来。','781年所立碑石以汉文主体和叙利亚文姓名等材料，保存唐代景教的教义表达、人员记忆与朝廷关系。它本身是重要物证，与碑文所叙述的早期事件属于不同证据层次。','碑文显示译写不是简单替换名词，而是借用汉语熟悉的词汇表达新的信仰概念。它也有纪念与赞颂目的，既可研究跨文化交流，也需分析叙述中的修辞和选择。','本条与635年的来华追述分开设置。碑不能证明景教在唐代各地始终兴盛，也不能仅凭其中的政治称赞就推断所有统治时期都提供同等宽容。',certainty='碑刻实物与纪念文本')
 add(787,'nicaea','第二次尼西亚会议与圣像敬礼','会议与教义','伊琳娜、塔拉修斯','nicaea2','会议恢复对圣像的敬礼，并区分敬礼与唯独归于上帝的崇拜。','787年的会议在伊琳娜时期召开，以圣像问题为核心，对图像的使用与敬礼作出规定。会议文件借助传统和道成肉身论述，区分不同意义的尊敬与崇拜。','这并未使帝国中的圣像争论立刻结束，九世纪又有新的禁像阶段。西方对会议译文和术语的理解也出现争议，说明同一决议在不同语言环境中可能获得不同接受。','本条不能与325年的第一次尼西亚会议混同。会议编号及其权威的认可依教会传统而异，本站呈现文件与接受史，不以一条标签裁定后世所有图像实践。')
 add(800,'rome','查理曼加冕与拉丁基督教世界','宗教与政治','查理曼、利奥三世、艾因哈德','einhard','罗马的帝国加冕把法兰克王权、教皇保护与帝国名号重新连接。','800年圣诞节，查理曼在罗马获得皇帝冠冕。此前法兰克统治者已经介入教皇保护、教会改革和修院教育，加冕使这些合作进入新的象征和政治层次。','拜占庭方面对皇帝名号与西方权力的理解并不相同；西方内部也存在王权与教皇权威的张力。学校、礼仪、文本校订和军事强制同时属于这一时代。','艾因哈德的传记写作晚于加冕，关于查理曼是否预知仪式的叙述应按作者立场阅读。不能把加冕直接称为现代欧洲国家诞生，也不能掩盖征服中的强制受洗与暴力。')
 add(843,'constantinople','圣像恢复与正教节记忆','礼仪与文化','狄奥多拉、麦多迪乌斯','nicaea2','九世纪圣像敬礼的恢复成为拜占庭教会每年纪念的重要事件。','在第二轮禁像政策之后，843年首都恢复圣像敬礼，后来形成正教节的纪念传统。礼仪文本把这一转折表达为信仰的胜利，但现实的教会整合仍需时间。','这一节点要放在八世纪会议与九世纪帝国政策反复之间理解。皇室、宗主教与修士共同参与，图像是否使用以及如何解释，也与群体记忆和政治合法性相连。','本站链接787年会议决议作为较早的教义背景，而不是把它伪称843年的现场记录。每年的礼仪纪念与历史事件之间有关联，也有后世增订与解释的层次。',certainty='历史转折 · 参考较早会议文书')
 add(863,'moravia','西里尔、美多迪乌与斯拉夫语礼仪','文献与翻译','西里尔、美多迪乌、拉斯季斯拉夫','cyril','使团通过文字与译经工作，使斯拉夫语进入重要的教会与文化网络。','863年前后，两兄弟应邀前往大摩拉维亚地区，推动以当地语言开展教导和礼仪。与他们相关的文字创造和翻译事业，后来经门徒在其他斯拉夫地区继续发展。','他们必须与当地统治者、拉丁教士、罗马和君士坦丁堡交涉。语言选择既关系人们能否理解礼仪，也涉及教会管辖与政治独立，不能仅当成纯粹语言技术问题。','传统上相关早期文字通常指格拉哥里字母，不能简单说兄弟二人直接创造了后来定型的西里尔字母。链接为1985年的纪念与历史回顾，属于后世教会自述，非九世纪原件。',certainty='使团纪年 · 后世教会回顾')
 add(865,'preslav','保加利亚王室归信与教会选择','归信与社会','鲍里斯一世、尼古拉一世','bulgaria','保加利亚统治者受洗之后，继续向不同教会中心询问制度与生活问题。','鲍里斯一世在九世纪中叶接受洗礼，随后在君士坦丁堡和罗马之间寻求适合本国的教会安排。归信不是政治活动结束，而是新的外交、制度和社会协商的开始。','尼古拉一世866年的答复讨论礼仪、婚姻、习俗和处罚等许多实际问题，显示王室受洗之后地方生活仍有大量不确定之处。斯拉夫语教育和教会组织随后继续发展。','本站以常用的865年作王室归信落点，具体受洗时间也有864年的纪年。普雷斯拉夫仅为区域代表，不能将后来的都城角色直接当作此次洗礼的确定现场。',certainty='864—865年纪年并存',label='约公元864—865年')
 add(910,'cluny','克吕尼：修院自治与改革网络','修道与敬虔','阿基坦的威廉、贝尔诺','cluny','创建文书对院长选举、修院财产与保护作出安排，后来形成广泛修道联系。','克吕尼创建文书将土地与资源献给修道生活，并对世俗干预、院长选举和罗马保护作出安排。捐赠者也以祈祷和灵魂得救解释自己的行为，财产与敬虔在文书中紧密相连。','克吕尼后来发展出跨地区修院网络，对礼仪、纪念亡者与教会改革产生影响。然而文书中的自治理想并不意味着修院完全脱离贵族、地方政治和社会经济。','910年是创建节点，后来的大规模建筑和组织不能全部归到这一年。阅读创建文书时应区分法律愿望、宗教修辞及实际实施，不能将修院改革等同现代个人宗教自由。')
 add(988,'kyiv','罗斯受洗与基辅教会','归信与社会','弗拉基米尔、安娜','rus','统治者受洗与拜占庭婚姻联系，推动罗斯地区教会和文化的长期发展。','《往年纪事》等材料把弗拉基米尔的受洗与政治选择、拜占庭婚姻及基辅群体洗礼联系起来。988年成为罗斯基督教化记忆的核心年代，但历史过程远比一场仪式漫长。','礼仪、文字、建筑和修道网络随后逐渐发展，既接受拜占庭影响，也在当地社会中形成新的实践。此前罗斯已存在基督徒，王室接受信仰并不是一切活动从零开始。','编年史的宗教选择故事写作晚于事件，须区分象征性叙事与独立证据。中世纪罗斯不等于任何现代民族国家，本站不从宗教起源故事推出今天的领土或文化独占权。',certainty='传统纪年与后期编年')
 add(1054,'constantinople','1054年的决裂：漫长分歧中的节点','分歧与合一','米海尔·凯鲁拉里乌斯、亨伯特','schism','罗马使节与君士坦丁堡之间的相互谴责，后来成为东西教会分裂的标志年代。','1054年罗马使节与君士坦丁堡宗主教方面的冲突，以针对特定人物的谴责文书告终。它发生在语言、礼仪、教会管辖、教皇权威和帝国政治长期争论的背景中。','这一事件当时并未使所有东、西方基督徒立刻停止来往。后续冲突、合一尝试，特别是1204年首都被攻占等经历，使分裂的群体记忆不断加深。','1965年的共同声明回顾并撤除相关谴责的记忆与教会隔绝，不能等同于恢复完全共融。本站不把1054年写成全世界教会一夜之间整齐分成两个现代宗派的日子。',certainty='历史节点 · 参考双方共同回顾')
 add(1075,'rome','格列高利改革与教皇权威','制度与权威','格列高利七世、亨利四世','dictatus','《教皇敕令》中的权威主张与叙任权争议，引出教会、君王与主教之间的长期冲突。','格列高利七世时期的改革反对圣职买卖和某些世俗任命方式，强调教会纪律及罗马主教的地位。1075年的简短命题汇集强烈的教皇权威主张，成为理解争论的材料。','主教同时承担宗教职分与土地、司法和王国治理责任，任命问题因此无法仅在神学层面解决。亨利四世及其支持者对教皇的要求提出反对，争执波及诸侯和地方教会。','《教皇敕令》的文书功能和传播范围须谨慎处理，不能直接当成已获全欧洲认可的完整法典。卡诺莎会面也没有终结冲突，后来仍须通过多种协定寻求安排。')
 add(1095,'clermont','克莱蒙号召与第一次十字军','冲突与暴力','乌尔班二世、富尔彻','urban','教皇号召武装远征，结合朝圣、赎罪、援助东方和拉丁社会的多种诉求。','乌尔班二世在克莱蒙的号召鼓励武装人员前往东方，回应拜占庭方面的求援，也赋予远征朝圣与赎罪的意义。领主、骑士、平民和教士参加的动机并不完全相同。','演说的现存版本来自不同作者，并且多在事后写成。比较它们能看到对圣地、苦难和宗教义务的不同强调，而不能把所有版本拼成一份逐字可靠的现场演讲稿。','十字军运动包含宗教信念，也造成征服、掠夺和对不同群体的伤害。本站将1096年莱茵河袭击和1099年耶路撒冷暴力另设节点，不把整个过程只写成单方面的英雄叙事。')
 add(1096,'mainz','莱茵河犹太群体遭到袭击','冲突与暴力','莱茵河犹太群体、当地十字军','mainz','第一批远征者及地方暴力波及犹太居民，美因茨等地留下惨烈记述。','1096年部分远征者和地方参与者袭击莱茵河流域犹太群体，美因茨等地发生杀戮与强迫改宗。希伯来编年记述受害者的选择与苦难，为这段历史保留不可替代的声音。','一些教会领袖和地方官员尝试保护犹太人，另一些人则参与、纵容或无力阻止暴力。解释事件需要具体辨认行动者，不能以抽象的文明冲突遮蔽当地责任。','编年作者具有纪念与宗教解释的目的，不等于材料可以忽略。地图仅标美因茨作为多城暴力的一处节点；反犹指控属于迫害者的错误指控，本站不将其作为可信历史事实复述。')
 add(1099,'jerusalem','攻占耶路撒冷与宗教暴力','冲突与暴力','第一次十字军、耶路撒冷居民','jerusalem','远征军攻占城市后发生杀戮，拉丁统治的建立改变当地不同宗教群体的处境。','1099年远征军攻入耶路撒冷，随后对居民实施杀戮和掠夺。拉丁、阿拉伯等不同叙述对规模、场景和意义有不同表达，但城市征服中的暴力不能因作者宗教立场而被抹去。','拉丁王国和新教会机构随后形成，东方基督徒、穆斯林和犹太群体面临不同处境。取得圣地不等于所有基督徒获得共同利益，拉丁和东方教会之间同样存在管辖与财产矛盾。','中世纪记述中的夸张数字与圣经式意象不应逐字当作统计数据。本站把攻城与后来长期统治分别理解，不依据政治色块推断全城居民信仰或支持征服的意愿。')
 add(1122,'worms','沃尔姆斯协定与叙任权妥协','制度与权威','加里斯都二世、亨利五世','worms','对主教的宗教授职与世俗权利作出区分，为长期政教争议提供阶段性安排。','1122年教皇与皇帝方面的文书分别规定选举、祝圣及世俗权利的授予。皇帝放弃以戒指和牧杖授予宗教职分，同时保留在某些地区参与选举及授予世俗权利的安排。','这是一种针对当时帝国政治与教会机构的妥协，并未消除皇帝、教皇、诸侯和主教之间所有冲突。各地区的条款和实际执行也不是完全相同。','协定不能解释为现代国家与教会已经彻底分离。它所区分的权利嵌在土地、效忠与职分体系中，阅读两方文书才能看见双方让步与保留，而不只是单方胜利。')
 add(1141,'bingen','希尔德加德开始写作《知路》','女性与教会','宾根的希尔德加德','hildegard','女修院领袖以异象、书信与音乐参与更广泛的宗教和公共生活。','希尔德加德以1141年开始记录重要异象为其写作转折，《知路》等作品把神学图景、劝诫与修道经验结合。她也通过书信联系教会领袖和政治人物，参与超出修院围墙的讨论。','她的活动显示中世纪女性可以在特定制度与敬虔语言中争取发言空间，同时也受到教会审批、性别规范和修院资源的限制。音乐、医疗和自然知识著作应按各自文类阅读。','链接为后世教会对其生平与作品的回顾，不是1141年原稿。本站不把异象的宗教意义等同现代医学诊断，也不将一位著名女性的经历推广为所有女性共有的生活条件。')
 add(1173,'lyon','瓦勒度与平信徒讲道','更新与改革','瓦勒度、里昂的贫穷者','waldo','以贫穷、福音生活和俗语讲道为诉求的群体，引发教会授权与纪律争议。','瓦勒度在里昂的转变传统通常放在1170年代，其追随者强调贫穷、阅读福音和公开劝讲。他们对基督徒生活的更新诉求，与教会对谁有资格讲道的制度要求相碰撞。','早期文献主要由外部编年者及反对者保存，群体名称、主张和后续发展不能一概而论。后来瓦勒度派经历迫害、迁徙，并在近世与改革宗网络形成新的联系。','本站以约1173年作运动兴起的落点，不把后来的全部信条归给创始人。也不将中世纪所有改革群体都写成十六世纪宗教改革已经完整定型的预备版本。',certainty='起源约年与外部记述',label='约公元1173年')
 add(1204,'constantinople','第四次十字军攻占君士坦丁堡','冲突与暴力','第四次十字军、尼基塔斯·霍尼亚提斯','fourth','原定远征转向基督教帝国首都，掠夺与拉丁统治加深东西教会创伤。','1204年第四次十字军攻占君士坦丁堡，出现掠夺、财产转移和圣物流散。远征的转向与债务、威尼斯利益及拜占庭皇位争夺等因素交织，不能只用单一宗教理由解释。','随后建立的拉丁帝国及教会安排改变当地权力结构，也加深希腊和拉丁基督徒之间的不信任。拜占庭继承政权继续存在，1261年的收复又开启新的阶段。','不同亲历者与后世作者对事件的辩解和谴责不相同。阅读时应区分参与者的责任和所有西方基督徒的身份，不把一次暴力自动扩大成任何现代群体共同承担的永恒罪责。')
 add(1209,'assisi','方济各与贫穷的共同生活','修道与敬虔','阿西西的方济各、克拉拉','francis','城市中的福音生活和兄弟团体，逐步形成托钵修会及相关女性修道网络。','方济各及同伴在十三世纪初以贫穷、劝讲和共同生活回应城市社会，传统以1209年前后的认可作为团体形成的重要节点。克拉拉及女性群体随后发展自身修道生活。','新的团体必须处理流动讲道、学习、财产与教会服从之间的关系。随着人数与机构扩大，如何忠于贫穷理想引发持续争论，不能把后来的修会组织视为起初已经全部设计完成。','本条链接1223年正式会规，明确区分较早形成过程与后来的规范文本。晚出的传奇故事可以呈现敬虔记忆，但不应未经比较就全部当作方济各本人可确证的言行。',certainty='形成阶段 · 参考后续会规')
 add(1215,'rome','第四次拉特朗会议与中世纪社会','会议与教义','英诺森三世','lateran','会议涉及信仰、圣礼、教士教育和社会纪律，也包含对其他群体的限制。','1215年的会议在罗马讨论信仰与教会治理，对告解、圣餐、教士训练、主教责任和异端问题等作出规定。它体现拉丁教会试图以制度处理广泛社会事务的能力和抱负。','这些规定不只关系教牧生活，也关系犹太人、穆斯林及被判为异端者的社会处境。讨论牧养规范时，同样需要说明歧视和强制所造成的后果，不能仅列举组织成就。','法令是规范性文件，地方实施并不均匀。会议对某些教义术语的确认，也不是相关信仰第一次出现；本站避免把复杂传统压缩成某年突然发明的一项制度。')
 add(1253,'karakorum','鲁布鲁克在蒙古世界的见闻','跨洲传播','鲁布鲁克、蒙哥汗、东叙利亚基督徒','rubruck','拉丁修士的旅行记呈现蒙古宫廷的多宗教交流，以及当地基督徒的多样处境。','鲁布鲁克于1253年开始东行，后来抵达蒙古宫廷，其报告涉及佛教徒、穆斯林、不同基督徒和宫廷礼仪。旅行者试图解释自己熟悉之外的语言、社会和信仰生活。','他对东叙利亚基督徒的批评反映拉丁修士的判断，也揭示基督徒彼此并不总能相互理解。多宗教辩论和宫廷接待应放在蒙古统治者的政治实践中阅读。','1253年为启程落点，抵达和离开分属后续年份。哈剌和林图钉表示旅程核心节点，不复原整条路线；旅行者使用的旧称和负面判断不作为本站对当地群体的定论。',certainty='1253—1255年旅行',label='公元1253—1255年')
 add(1265,'rome','阿奎那与经院神学','文献与翻译','托马斯·阿奎那','aquinas','以问题、异议与答复组织神学论证，连接圣经解释、哲学及大学与修会教育。','阿奎那在十三世纪中期发展系统神学教学，《神学大全》通常从1265年前后起草。他运用问题、异议和答复的形式，把经文、教父与亚里士多德传统放入论证。','经院研究依赖跨语言翻译与评论网络，包括希腊、阿拉伯语和犹太思想世界的贡献。大学与托钵修会既推动教学，也围绕权威、理性和学术职分发生争论。','罗马是开始编写《神学大全》时期的重要背景，巴黎等地也是其教学生涯的节点，全书并非在一地一时完成。著作后来取得的权威地位不能投射成作者生前毫无争议；本条也不把经院思想简化为全部中世纪基督徒共同使用的一套方法。',certainty='起草约年 · 教学中心定位',label='约公元1265年起')
 add(1287,'tabriz','拉班扫马：从东方前往欧洲','跨洲传播','拉班扫马、雅巴拉哈三世、阿鲁浑','sawma','出自中国北方的东叙利亚修士，代表伊儿汗国出访欧洲，展现双向的欧亚交流。','拉班扫马与马可原从中国北方地区西行朝圣，后来进入东叙利亚教会和蒙古政治网络。1287年他受命出访欧洲，拜访教会领袖和君王，参与伊儿汗国的外交尝试。','旅程让东方基督徒成为观察欧洲礼仪、城市与圣物的主体，纠正只有西方旅行者向外发现世界的单线叙事。其出使也涉及反马穆鲁克联盟等实际政治目标。','存世旅行记以叙利亚文传承，文本形成与翻译需留意。图上以大不里士区域代表使团的出发背景，不把所有会晤串成无间断的已复原航线，也不以旧称聂斯脱里派概括其全部信仰。')
 add(1305,'beijing','孟高维诺在元大都的报告','跨洲传播','孟高维诺、元代基督徒','corvino','方济各会士的书信记述大都教堂、教育和翻译，也反映不同基督徒群体间的竞争。','孟高维诺在元代大都活动，并于1305年寄出有关教堂、教学与翻译的报告。他描述接触的不同群体、获得支持的情形，以及自己认为面临的困难。','这一时期中国既有东叙利亚传统，也出现拉丁教会机构，二者关系并非总是合作。传教士关于受洗人数和成功的叙述需要结合书信的募援目的与其他材料比较。','本条以书信年份为节点，不称1305年为基督教首次入华。北京代表元大都区域，现代城市格局和现存教堂不能直接当作当年建筑的原址复原。')
 add(1309,'avignon','阿维尼翁教廷与跨国行政','制度与权威','克勉五世、彼特拉克','avignon','教廷在阿维尼翁地区长期居留，使罗马主教的行政网络与欧洲政治关系发生变化。','1309年起教廷在阿维尼翁地区居留，随后形成持续数十年的行政、财务和文化中心。它既保持跨国教会网络，也深受法国王权及欧洲政治环境影响。','彼特拉克等作者以激烈修辞批评教廷，提供当时不满的重要声音，但不能把文学谴责当作所有机构生活的完整统计。财政、任命和主教权利的争议继续累积。','教廷驻地与主教座的名义位置不完全相同，也不表示每位教皇都是法国国王直接控制的傀儡。阿维尼翁居留与1378年后多位教皇竞争是相关而不同的阶段。')
 add(1348,'avignon','黑死病中的照护、恐惧与迫害','社会与苦难','克勉六世、欧洲城市居民','plague','瘟疫重创教牧与社会生活，同时引发照护行动、忏悔运动和对少数群体的暴力。','十四世纪中叶瘟疫在欧洲和地中海造成严重死亡，教士、修士与平民同样遭难。病人照护、丧葬与圣事需求增加，许多地方原有组织难以维持，也出现新的敬虔实践。','恐惧之中发生针对犹太群体的错误投毒指控与屠杀，亦有教会领袖发文反对。解释这一历史必须区分疫病传播、当时的理解和迫害者的谣言，不能借历史文本传播错误因果。','1348年是多地区灾难的一处落点，阿维尼翁只是观察节点。所链接薄伽丘的描写主要涉及佛罗伦萨，提供比较材料，不伪称为阿维尼翁当地的逐日死亡记录。',certainty='多地过程 · 比较城市记述')
 add(1378,'avignon','拉丁教会的多教皇竞争','分歧与合一','乌尔班六世、克勉七世','constance','罗马与阿维尼翁的竞争性主张，使王国、教区和大学卷入共同合法性的危机。','1378年教皇选举及其合法性争议后，出现分别以罗马和阿维尼翁为中心的竞争主张。不同君王、教区和修会选择不同服从对象，教会行政与普通信徒也受到影响。','大学学者、王室和教会人士提出辞职、仲裁和大公会议等解决方案。1409年的比萨会议未能立即统一局面，反而一度出现三位竞争者，显示合一方案也可能加剧危机。','这里的西方大分裂不同于1054年东西教会关系的变化。链接会议文件用于理解后来处理危机的方案，不应被说成1378年当事人已经预先达成的共同协议。',certainty='制度危机 · 参考后续会议')
 add(1382,'london','威克里夫争论与文本流传','更新与改革','约翰·威克里夫、罗拉德派','wycliffe','围绕教会财产、圣礼与权威的争论，经大学、讲道和抄本网络继续传播。','1382年的谴责及威克里夫的答辩，显示英格兰围绕教会财产、圣餐与权威的激烈争论。其相关思想也通过学术和抄本网络进入波希米亚，影响后续改革讨论。','与威克里夫相关的俗语圣经运动由多人参与，不能把全部译文归给他一人。被称为罗拉德派的群体也并非观点完全相同，他们受到的审查和支持随地区及年代变化。','1382年的伦敦会议与威克里夫在牛津的教学须分别定位；布拉格属于思想随后传播的重要节点。本站不把胡斯与威克里夫的主张视为完全一致，也不把后来的译经成果全部归到一人一地。',certainty='英格兰事件 · 布拉格为后续传播节点')
 add(1415,'constance','胡斯审判与波希米亚改革','更新与改革','扬·胡斯、西吉斯蒙德','hus','胡斯在康斯坦茨被定罪并处死，改革诉求和教会权威危机进一步激化。','胡斯因讲道、教会改革和权威问题与对手冲突，前往康斯坦茨后遭到拘禁、审判并于1415年被焚刑。保护承诺、审理程序和被谴责的主张成为长期争议焦点。','他的遭遇在波希米亚引起强烈反响，后续胡斯派运动包含不同路线，也与王位继承和地方政治相连。反对腐败、圣餐实践和教会组织的问题不能全部归为一个口号。','审判材料与胡斯自辩需要并读，后世纪念也有各自宗派立场。本站不把胡斯简单描绘成已经完整接受十六世纪所有新教教义的人，也不以被定罪的身份替代对其实际思想的考察。')
 add(1417,'constance','康斯坦茨会议与结束西方分裂','会议与教义','马丁五世、让·热尔松','constance','选举马丁五世为恢复拉丁教会共同服从提供节点，大公会议权威问题仍持续争论。','康斯坦茨会议在1414—1418年间处理教皇竞争、改革与被判为异端的问题。1417年选出马丁五世，为重建较广泛的共同服从提供重要节点，但并非所有人立即接受。','会议中的大公会议主义主张，以普遍教会及会议权威限制或处理教皇危机，日后与教皇权威发生新的冲突。制度上的解决并未自动完成财政、任命与地方纪律改革。','会议也与胡斯和布拉格的耶罗米的处刑相连，合一成就不能抹去强制和暴力。本站把会议议程分别说明，不把恢复统一写成所有参与者都受益的简单圆满结局。')
 add(1439,'florence','佛罗伦萨合一尝试与接受难题','分歧与合一','若望八世、优金四世、以弗所的马可','florence','东西方代表签署合一文书，实际接受却因神学、政治与地方抵制而受阻。','1439年东西方代表在佛罗伦萨达成合一文书，讨论圣灵发出、教皇地位及其他争议。拜占庭方面寻求西方援助的政治压力，与真实的神学讨论共同构成会议背景。','部分代表签署并不代表所有教会和信徒立即接受。以弗所的马可等反对者及回国后的争论，使合一在东方难以落实；随后另有与其他东方群体相关的文书。','不能把会议简单说成东方用信仰交换军事援助，也不能将签署当作分裂已永久解决。不同文书与教会对象须分别理解，本站不以一次会议代替整个接受史。')
 add(1453,'constantinople','奥斯曼征服与正教会的延续','宗教与政治','穆罕默德二世、根纳季奥斯','fall','君士坦丁堡陷落结束拜占庭帝国，正教会在新的统治关系中继续发展。','1453年奥斯曼军攻占君士坦丁堡，拜占庭帝国的政治结构终结。围城、死亡、俘虏与人口变动深刻改变城市，但东方教会并未因此消失，宗主教制度随后在新条件下延续。','奥斯曼统治者与教会领袖之间的安排涉及税赋、司法、保护和限制。后来逐渐形成的制度不能全部当作征服当日已经完整发布的一套固定规则。','不同作者对陷落的宗教解释与战争描写各有立场。地图显示政权变化而非信仰瞬时替代，也不把所有正教会的历史缩小为首都一座城市的命运。')
 add(1455,'mainz','古登堡圣经与印刷时代','文献与翻译','约翰内斯·古登堡','gutenberg','金属活字印刷的拉丁圣经成为欧洲出版史的重要物证，改变文本复制与传播条件。','十五世纪中叶美因茨的古登堡圣经采用金属活字印刷，通常约定于1454—1455年完成。昂贵的纸张、排印、校对与装饰，使它仍与手抄本审美及富裕读者密切相连。','印刷逐渐扩大文本生产规模，为经文、讲道、小册子和论战提供条件，但不会自动带来统一读法。出版者、城市监管、审查和读者识字程度同样影响传播。','本站以1455年为近似完成节点，不称其为世界最早的印刷书或最早活字印刷。东亚已有更早印刷传统，欧洲后来的宗教改革也不能仅用一项技术来解释。',certainty='出版约年',label='约公元1454—1455年')
 add(1491,'mbanza-kongo','刚果王室受洗与非洲教会艺术','非洲教会','恩津加·恩库武、阿丰索一世','kongo','刚果王室与葡萄牙建立宗教联系，当地基督徒随后在语言、教育与艺术上作出自己的表达。','1491年刚果王恩津加·恩库武受洗并采用若昂之名，王室与葡萄牙及罗马的宗教外交联系逐步发展。后继者阿丰索一世推动教育、教牧训练和基督教实践。','当地工匠以刚果的视觉和象征语汇创作十字架等艺术，显示非洲人对新信仰的主动解释。王室与贵族的选择并不等于所有地方实践立即一致，冲突与混合也持续存在。','相关物件与王室书信应和欧洲传教报告并读。刚果不是十六世纪葡萄牙的简单被动附庸；同时不能忽视贸易、权力与奴隶掠夺给社会和教会造成的深刻伤害。')
 add(1516,'basel','伊拉斯谟的新约与人文主义校勘','文献与翻译','伊拉斯谟、约翰·弗罗本','erasmus','希腊文新约及拉丁修订本出版，让语文学、经文解释与教会改革诉求进一步交织。','1516年伊拉斯谟在巴塞尔出版希腊文新约及其拉丁文修订本和注释，推动读者比较文本与译法。出版工作依赖手稿、排印与仓促校对，后续版本继续修订。','人文主义的返源诉求帮助学者重读经文和教父，但它不自动导向相同的宗教立场。伊拉斯谟批评教会弊端，也与路德在意志和恩典等问题上出现公开分歧。','本条链接图书馆对1516年版本及其编辑工作的馆藏说明，并非抄录整部新约。不能把印本称为未经编辑选择的原始新约，也不把人文主义等同于某一个新教宗派。',certainty='出版纪年 · 参考后续论争')
 add(1517,'wittenberg','九十五条论纲与赎罪争论','宗教改革','马丁·路德、约翰·台彻尔','luther','路德针对赎罪券与悔改提出论辩，印刷和书信让争论迅速越出大学环境。','1517年路德围绕赎罪券、悔改和教会惩罚提出九十五条论题，并向有关教会权威致信。文本仍处在晚期中世纪的神学和制度语境中，不能当作后来全部新教信条的缩写。','印刷、翻译与城市联系使论辩获得远超预期的传播。财政、牧养与权威问题逐渐发展为更广泛的圣经解释和教会改革冲突，参与者也不断调整自己的立场。','10月31日钉门的具体场景属于仍需比较证据的历史问题；论纲和相关书信的传播更有直接文献支撑。本站不依单一戏剧化场景解释整个改革，也不把赎罪券简化成教会明文出售一切罪的免除。')
 add(1521,'worms','沃尔姆斯议会：改革与帝国权力','宗教改革','马丁·路德、查理五世','diet','路德在帝国议会接受质询，是否撤回著作的问题使神学冲突进入法律与政治层面。','1521年路德在沃尔姆斯面对帝国与教会方面的质询，被要求确认并撤回相关著作。他以经文与论证为自己的立场辩护，随后遭到帝国禁令，但也获得地方统治者保护。','事件说明宗教改革既涉及个人良知和文本解释，也需要在帝国法律、诸侯权利与保护关系中生存。不同城市和领地的后续政策并不一致，冲突远未在议会结束时解决。','著名的此乃我立场等措辞的传承应与较可靠的记录区分。本站不把演说写成现代完全宗教自由的声明，也不将政治保护解释为所有改革参与者都免于迫害。')
 add(1523,'zurich','苏黎世改革与城市议会','宗教改革','慈运理、苏黎世市议会','zwingli','公开辩论、经文讲解和市政决定推动改革，形成与维滕贝格不同的路径。','1523年前后的苏黎世辩论把慈运理的讲道和教会改革要求提交城市政治机构处理。礼仪、斋戒、图像与牧职生活等问题逐步进入新的市政安排，改革不是只靠一位讲道者独立完成。','苏黎世路线与路德的神学既有共同点，也在圣餐等问题上发生明显分歧。城市所支持的改革与反对婴儿洗礼的群体之间同样出现冲突，后来导致驱逐和处刑。','本条链接1529年马堡会谈的慈运理报告，以比较后来的圣餐争论，不能当作1523年辩论逐字记录。不要把所有改革宗群体都视为最初已经拥有相同制度。',certainty='城市改革 · 参考后续论争')
 add(1525,'zurich','再洗礼群体与自愿的信仰共同体','宗教改革','康拉德·格列伯、费利克斯·曼茨','anabaptist','早期弟兄群体重新施洗，挑战城市教会秩序，后来遭到多方迫害。','1525年苏黎世出现反对婴儿洗礼、强调信仰认信之后受洗的群体。他们主张教会成员需要作出自己的信仰回应，与把城市居民普遍纳入教会的制度发生冲突。','这些群体后来被统称再洗礼派，但各地在财产、政治和末世观上差异很大。部分弟兄会强调非暴力、纪律与彼此帮助，亦有其他激进路线，不能以一种行为概括全部群体。','本条以1527年施莱特海姆文书说明一支后续立场，不将它当作1525年所有参与者共同签署的纲领。被天主教和新教政权迫害的经历，也不能因此忽略群体内部的具体差异。')
 add(1526,'mbanza-kongo','阿丰索一世的书信与奴隶贸易','非洲教会','阿丰索一世、若昂三世','afonso','刚果国王向葡萄牙王投诉掠夺和非法奴役，展现非洲基督徒对大西洋秩序的批评。','阿丰索一世在1526年的书信中申诉贸易者掠走自由民、贵族子女等问题，要求限制和监管人口买卖。信件使我们听见非洲统治者对葡萄牙关系及当地社会危机的直接表达。','他把教育、教牧和外交联系与王权治理结合，也身处当时既有的奴役制度之中。批评非法掠夺不能自动解释为现代意义上反对一切奴隶制度，应准确区分信件所提出的要求。','书信显示基督教联系并未阻止欧洲商业暴力，非洲人也不是没有回应的被动对象。本站将王室的宗教选择与贸易伤害同时呈现，不用传教成功叙事遮蔽受害者的处境。')
 add(1527,'schleitheim','施莱特海姆信条与弟兄群体','会议与教义','米迦勒·萨特勒、瑞士弟兄会','anabaptist','文书讨论洗礼、纪律、圣餐、牧者和武力，体现早期再洗礼运动的一种组织选择。','1527年的施莱特海姆文书以若干条款组织共同信仰与生活，强调认信后的洗礼、教会纪律、圣餐及与某些世俗实践的区分。它也拒绝用武力承担某些政治角色。','这使读者看到宗教改革并非只有路德宗和改革宗两条路线。团体的存续依赖聚会、书信、迁徙及彼此支持，也面临来自多方当局的压制，萨特勒同年被处死。','信条代表一支特定弟兄会的立场，不能用来涵盖所有再洗礼群体，更不能与后来明斯特政权的暴力路线混为一谈。对非暴力的主张与现实中的迫害须分别叙述。')
 add(1530,'augsburg','奥格斯堡信纲：信仰的公开陈述','会议与教义','菲利普·墨兰顿、马丁·路德、查理五世','augsburg','诸侯与城市向帝国提交信仰陈述，解释教义和改革，也寻求共同讨论的语言。','1530年奥格斯堡帝国议会上，墨兰顿起草的信纲被提出，陈述路德派诸侯和城市的核心立场。文本区分教义陈述与有关教会弊端的争议，试图说明改革与古代信仰的连续性。','信纲既是神学文件，也进入帝国谈判与领地政治。后来的答辩、修订和信条汇编继续塑造路德宗身份，而反对者并未因公开宣读立即接受其解释。','信纲不能当作所有新教共同签署的文件，也不等于1555年的宗教和约。本站以文书的自我陈述为阅读入口，同时保留其在论战与政治保护背景中的形成条件。')
 add(1534,'london','至尊法案与英格兰的制度转折','制度与权威','亨利八世、托马斯·克伦威尔','supremacy','议会确立王室对英格兰教会的最高治理地位，与罗马管辖发生制度断裂。','1534年的至尊法案将英格兰教会最高治理权归于君王，回应婚姻、继承与罗马权威争议。随后的誓言、财产与修院政策使制度变化进入个人生活和地方社会。','与罗马断裂不等于亨利八世立刻接受全部大陆新教教义。圣餐、礼仪、经文语言和教会纪律在后续几位君主时期多次改变，也出现天主教恢复与新的迫害。','改革不能只解释为国王的一桩婚姻，也不能忽视王朝利益和强制。本站区分制度断裂、教义调整与后来安立甘传统的发展，不把英格兰全体居民描绘成一致支持者。')
 add(1536,'geneva','加尔文与改革宗的教学网络','宗教改革','约翰·加尔文、纪尧姆·法雷尔','calvin','《基督教要义》初版与日内瓦改革，开启持续修订、教导及跨国联系。','1536年《基督教要义》初版出版，加尔文同年参与日内瓦改革。全书后来多次扩充，他在日内瓦的工作也经历驱逐、返回及与城市机构之间的长期协商。','讲道、学校、牧者训练和书信网络使日内瓦影响移民及其他地区群体。改革宗的发展并非仅由日内瓦单向输出，各地政治条件和已有改革传统同样重要。','所链为后期修订版的旧译，不伪称1536年初版逐字文本。必须同时考察城市纪律、对异见者的强制和流亡者获得的支持，不能把这座城市简化为完全自由或完全一致的理想共同体。')
 add(1540,'rome','耶稣会获准与天主教更新','更新与改革','依纳爵·罗耀拉、保禄三世','jesuit','新的修会以灵修、教育和差遣服务展开，成为天主教改革及跨洲交流的重要力量。','1540年教皇批准耶稣会，依纳爵与同伴把灵修操练、教会服从和随时接受差遣结合。团体后来迅速建立学校，参与讲道、教理教育、外交和远距离传教。','天主教更新并非仅仅被动回应路德，改革诉求在更早时期已经存在。耶稣会的发展与主教改革、其他修会、女性团体和地方信徒的实践共同构成更广泛的变化。','官方修会史可以说明自我理解，但应与当地群体和不同立场的文献比较。教育与跨文化学习的贡献，也不能遮蔽传教同殖民权力、强制和宗教排斥发生联系的场景。')
 add(1542,'goa','沙勿略抵印与印度教会的多重历史','跨洲传播','方济各·沙勿略、印度基督徒','xavier','耶稣会活动进入葡萄牙亚洲网络，同时与已有数百年历史的当地教会相遇。','沙勿略1542年抵达果阿，随后在印度沿海与其他地区活动。书信记述教导、洗礼、学校及人手不足，也向欧洲修会争取支持，具有明确的宗教动员目的。','印度已有叙利亚语传统的基督徒，不能以这次抵达作为印度教会史的开端。地方语言、渔民群体、王权及葡萄牙贸易保护等因素，都影响传教的实际发展。','1543年书信提供近时见证，仍需与当地材料比较。果阿作为殖民据点，后来亦出现宗教裁判制度；本站不把殖民政权、传教士和所有印度基督徒视为利益完全相同的一方。')
 add(1545,'trent','特伦托会议开幕与天主教改革','会议与教义','保禄三世、特伦托会议代表','trent','会议回应经文、传统、圣礼和教会纪律问题，并在多次中断之后继续召开。','1545年特伦托会议开幕，教义讨论涉及经文与传统、称义、圣礼及弥撒等改革争议。纪律改革涉及主教居住、教牧培训及教会治理，会议并不只处理对新教的谴责。','会议跨越数位教皇和欧洲战争，多次中断并曾转至博洛尼亚，最终于1563年结束。法令的实施仍依赖主教、学校、修会和地方信徒，无法在结束时自动完成。','本站区分1545年开幕与1563年结束两个节点。阅读会议文件应注意它以自身术语回应具体对手，不能把所有新教传统概括为同一种立场，也不把天主教更新完全归结为一次会议。')
 add(1550,'valladolid','殖民传教与原住民权利之争','社会与苦难','巴托洛梅·德·拉斯卡萨斯、胡安·希内斯·德·塞普尔韦达','las-casas','征服、传教与原住民处境引发激烈争论，教会人士并非都支持同一种殖民政策。','十六世纪美洲的修会传教与西班牙殖民统治紧密相连，也出现对强迫劳动和暴行的公开批评。拉斯卡萨斯等人的论述挑战某些征服理由，1550—1551年的巴利亚多利德辩论是重要节点。','原住民并非只有被动受教的角色，他们通过语言、图像、法律申诉和地方组织回应新秩序。教会中的照护与教育、参与强制及对殖民暴力的反对，需要同时考察。','地图标出辩论所在的巴利亚多利德，并另设墨西哥节点说明新西班牙背景；讨论对象不等于讨论会址。链接为拉斯卡萨斯较早的控诉文本及其后刊本传统，并非辩论的完整逐字记录。',certainty='1550—1551年辩论',label='公元1550—1551年')
 add(1549,'kagoshima','沙勿略与日本基督徒的起步','跨洲传播','方济各·沙勿略、弥次郎','japan','传教士、翻译者和当地支持者在九州建立联系，日本信徒成为后续传播的重要行动者。','1549年沙勿略抵达鹿儿岛，弥次郎等日本人的翻译和引介影响最初交流。传教士必须学习语言，重新选择表达上帝与教义的用语，也需与地方统治者和宗教群体交涉。','传播随后扩展到不同领地，商贸、领主利益、学校及在地教理人员都发挥作用。基督徒的生活不能只通过欧洲传教士的行程理解，日本信徒和家庭也持续组织群体。','1549年的书信反映早期观察和期待，并不能证明所有后来的结果。本站将欢迎、竞争和后来迫害分开叙述，不把日本描绘成始终一致开放或始终一致敌对的单一社会。')
 add(1555,'augsburg','奥格斯堡和约与有限宗教安排','宗教与政治','查理五世、斐迪南一世、帝国诸侯','peace','帝国承认天主教与奥格斯堡信纲相关群体的法律安排，仍排除其他重要信仰路线。','1555年的宗教和约为帝国内天主教和奥格斯堡信纲相关领地提供共存框架，处理领地宗教选择、迁出及教会财产等问题。这是长期战争与谈判后的法律妥协。','改革宗、再洗礼派等并未获得同等地位，教会领地与保留条款仍引发争端。统治者的选择和臣民的权利不同，领地内的信仰多样性并未因法律条文消失。','通常用教随国定概括和约，但这不能代替复杂条款，更不等于现代普遍宗教自由。本站将1530年的教义信纲与1555年的帝国法律区分，也不把它写成欧洲宗教战争的永久结束。')
 add(1560,'edinburgh','苏格兰信条与改革议会','宗教改革','约翰·诺克斯、苏格兰改革者','scots','议会与信仰陈述推动苏格兰改革，教会制度和王室关系随后仍持续变化。','1560年苏格兰议会通过改革措施，并接受改革者提出的信仰陈述。贵族联盟、法国联系、王室继承和讲道运动共同影响局势，不能只归因于诺克斯个人的演说能力。','教会如何治理、牧者如何供应以及学校如何建设，仍需随后多年的制度工作。长老制后来逐渐发展，王室与教会会议的关系继续争执，信条通过并非一切安排已经定型。','《苏格兰信条》属于特定时期的公开陈述，不是所有后来长老会文本的完全同一版本。改革中的反图像行动、财产变化和对天主教群体的压制也需要纳入历史，而不只描述教义成就。')
 add(1562,'avila','德肋撒与加尔默罗的更新','女性与教会','阿维拉的德肋撒、十字架的若望','teresa','新的修院实践、祈祷写作与女性组织能力，成为天主教更新的另一条重要线索。','德肋撒于1562年在阿维拉建立圣若瑟修院，推动更严格的共同生活与祈祷实践。她通过旅行、书信、筹款和谈判创建新的修院，并与教会审批及修会内部争议相周旋。','《自传》等作品不仅记录内在经验，也说明她如何在男性权威主导的制度中解释自己的行动。与十字架的若望有关的改革后来形成更广泛网络，但过程充满抵制与妥协。','不能将灵修写作当作所有女性生活的代表，也不把神秘经验直接归为某种现代心理诊断。改革首先关注特定修道实践，与同一时代的新教改革有交汇背景而不属于相同制度路线。')
 add(1563,'trent','特伦托结束：法令与地方实施','会议与教义','庇护四世、改革中的主教与修会','trent','会议结束之后，教牧训练、礼仪规范与纪律改革仍须长期落实。','1563年特伦托会议完成最后会期，正式法令为天主教教义和纪律提供重要规范。修院与主教职责、牧者培养及圣礼实践等要求，将影响其后数百年的地方教会生活。','法令是否实施取决于王权、主教资源、地方社会和修会网络。不同地区的节奏不同，标准化礼仪和教理材料也在后续年代编制，不能全部归为会议闭幕当天完成。','开幕与结束相隔十八年且多次中断。本站以两个节点呈现过程，避免把特伦托概括成一项只针对新教的防御措施，也不把拉丁西方的制度变化视为所有东方天主教礼仪同时同样改变。')
 add(1572,'paris','圣巴托罗缪日屠杀','冲突与暴力','凯瑟琳·德·美第奇、法国胡格诺派','paris','巴黎的政治危机演变为对胡格诺群体的大规模暴力，并扩散到其他城市。','1572年王室婚礼和宗教谈判背景下，巴黎发生针对胡格诺领袖及居民的杀戮，暴力随后扩散到法国其他地方。宫廷决定、城市动员与地方仇恨的关系，需要分别分析。','天主教和新教作者对阴谋、责任和受害人数有不同叙述，史料比较不能抹去屠杀本身。事件重创互信，迫使许多信徒迁徙或改变公开生活方式，也影响抵抗权理论。','受害数字不能仅取一份激烈论战文本当作精确统计。本站辨认具体行动者与政治条件，不把全部天主教徒或全部法国居民视为同一行动主体，也不把暴力当作任何信仰不可避免的结果。')
 add(1597,'nagasaki','长崎二十六人殉难与禁教前景','迫害与群体','保禄·三木、日本基督徒、丰臣秀吉','nagasaki','在长崎处死的日本与外来信徒，成为当地教会记忆的重要节点。','1597年二十六名日本及外来基督徒在长崎遭处死，受害者包括修会人员与平信徒。事件与丰臣政权、海外贸易、传教竞争和对外来势力的担忧有关，不能仅用单一原因解释。','当时传教和聚会并未立即在全日本完全终止，后续政策又多次变化。日本信徒、家庭和教理人员在不同压力下继续生活，其选择不只表现为欧洲传教士的在场与否。','本站依据机构历史分期说明事件，把1597年处刑与1614年全面禁教等节点分开。殉道记忆的宗教意义与有关审理、政策和人数的历史证据，应各自明确。')
 add(1598,'nantes','南特敕令与不对称的共存','宗教与政治','亨利四世、法国胡格诺派','nantes','在天主教王国框架下给予胡格诺群体有限保障，为宗教内战提供阶段性安排。','亨利四世1598年发布南特敕令，在恢复天主教公共秩序的同时，给予胡格诺群体某些礼拜、民事和安全保障。它试图在长期内战后，用复杂而不对称的规则建立共存。','保障取决于地点、法律身份及具体条款，地方执行仍有阻力。不同信仰群体并未因此成为完全平等的公民，武装据点和王权之间的关系也继续造成争端。','南特敕令不是现代普遍信仰自由宣言，其部分保障后来被削弱并最终于1685年撤销。后一个年份超出本篇章范围，在此仅作阅读提示，不在地图上虚构为1598年已经发生的结果。')
 add(1599,'kerala','乌代安普尔会议与马拉巴尔传统','制度与权威','阿莱克索·德·梅内泽斯、多马基督徒','diamper','葡萄牙教会势力推动地方会议，叙利亚语礼仪、教会管辖和文本审查成为争议核心。','1599年乌代安普尔会议在葡萄牙教会权力推动下召开，试图整顿当地多马基督徒的教义、礼仪和组织。对叙利亚文书籍的审查及礼仪调整，改变了原有教会联系。','当地群体早已拥有长期传统和跨印度洋网络，并非等待欧洲人建立的空白。归属罗马、拉丁化措施与地方反应是相关而不同的问题，参与者也并非意见一致。','本站链接该教会研究机构2021年发表的会议研究，标示其传统视角。后来的1653年誓言与教会重组超出本篇章终点，不将它提前写进1599年的现场，也不以外部异端标签取代群体自称。',certainty='会议纪年 · 地方教会自述')
 add(1601,'beijing','利玛窦抵京与中国合作者','跨洲传播','利玛窦、徐光启、李之藻','ricci','语言、数学、地图与信仰文本建立新的交流网络，中国士人和信徒主动参与翻译。','1601年利玛窦抵达北京，使耶稣会与明代宫廷及士人网络的联系进入新阶段。他在此前已长期学习汉语、撰写地图和宗教著作，抵京不是一场突然开始的文化相遇。','徐光启、李之藻等中国合作者参与翻译、出版和信仰辩护，选择哪些概念可以相通、哪些需要重新解释。科学知识与信仰传播有联系，却不能说接受数学就等于接受所有宗教主张。','链接为徐光启在后续危机中的辩护文本，用以呈现中国信徒声音，并非1601年的逐日行程。唐代和元代已有基督徒，近世传教不是基督教首次入华，也不代表所有士人都给予相同支持。')
 add(1614,'nagasaki','德川禁教与信仰的隐蔽延续','迫害与群体','德川家康、日本基督徒','nagasaki','全国性禁教政策与驱逐改变教会生活，地方群体在严密控制下采取不同应对。','1614年德川方面推行更广泛的禁教与驱逐，教堂、修院和公开教牧网络受到严重打击。不同领地的执行与后续措施逐渐加强，信徒的聚会、家庭和生活选择面临风险。','部分基督徒迁徙、隐匿信仰或在压力下公开放弃，部分继续秘密组织。不能将所有存续都归功于外来传教士，地方家庭、记忆与祈祷实践在缺乏公开机构时尤为重要。','机构资料中的潜伏基督徒传统延伸至更晚世纪，本条仅讨论本篇章时段的开端。国家政策不代表每位日本居民共同参与迫害，也不宜把不同地方的措施写成一天内完全相同地执行。')
 add(1618,'dordrecht','多特会议与改革宗内部争论','会议与教义','雅各布·阿民念、抗辩派、改革宗代表','dort','1618—1619年的会议回应抗辩派，形成关于恩典与救恩的信经。','多特会议于1618—1619年召开，讨论抗辩派提出的有关拣选、恩典与信徒坚忍等问题。来自不同地区的代表参与，会议法令成为许多改革宗教会的重要信仰文件。','争论与尼德兰的战争、执政者和城市政治相互交织，抗辩派代表的参与地位及会后被排除处境也需说明。改革宗内部并非从来只有一种无争议的解释。','多特信经是对特定争论的回应，不是加尔文全部思想的五句摘要。本站取开会年为节点，并说明会议延至1619年；链接为后世教会维护的文本版本，不能等同全部讨论记录。',label='公元1618—1619年')
 add(1618,'prague','三十年战争中的宗教与王朝','冲突与暴力','波希米亚等级会议、哈布斯堡王朝','war','布拉格危机开启长期战争阶段，宗派、王朝和地方权利的诉求交织。','1618年波希米亚冲突及布拉格掷出窗外事件后，战争逐渐扩大到帝国和欧洲多个地区。宗教权利、王位继承、领地自治与王朝安全共同推动局势，不能只用新教对天主教概括所有联盟。','战争给居民带来征粮、迁徙、疾病和人口损失，教会机构既组织照护，也卷入动员和强制改宗。战争后期的联盟常跨越宗派边界，显示国家利益与信仰认同并非总一致。','本条以1618年作为本轮战争的起点，不暗示此前宗教暴力不存在。链接1648年和约及机构导言，作为战争终局的比较资料，非1618年现场记录。地图不提供每场战役或行军的精确复原。')
 add(1632,'gondar','埃塞俄比亚的王室政策与信仰反抗','非洲教会','苏塞尼奥斯、法西利德、埃塞俄比亚信徒','ethiopia','强行推动罗马教会改革引发反抗，王室政策逆转，地方传统重新获得政治支持。','十七世纪苏塞尼奥斯支持与罗马的联系及耶稣会推动的改变，礼仪和教义措施引起激烈抵抗。政治冲突、强制与战事加深危机，1632年统治转折使宗教政策逆转。','法西利德随后支持当地正教传统，耶稣会势力逐渐被排除。埃塞俄比亚教会有自身古老的经文、礼仪和王国联系，不能把对拉丁化的抵制简单写成拒绝基督教。','贡德尔仅为高地区域代表，后来才成为新都，不伪称1632年退位仪式发生于现存宫殿。所链国会图书馆国别研究属于后世历史综合，旧术语须与埃塞俄比亚教会自述比较；不是1632年的现场记录。')
 add(1648,'munster','威斯特伐利亚：有限共存的新安排','宗教与政治','帝国诸等级、法国、瑞典','westphalia','和约处理战争、领土和宗教权利，为帝国内多个教派提供新的法律框架。','1648年在明斯特和奥斯纳布吕克等谈判形成的和约，结束三十年战争的主要冲突，重新安排领土、诸等级权利与宗教事务。改革宗在帝国宗教法律框架中的地位也得到确认。','具体安排涉及财产、基准年份、礼拜和少数群体权利，具有复杂条件。它并未给所有宗教与个人提供同等自由，也没有使欧洲和世界的宗教暴力就此消失。','本站以1648年作为中世纪到宗教改革时代篇章的终点，不把它称为现代国家主权或世俗社会在一天内的诞生。链接为其中一份和约文本，不能代替全部谈判文书与各地实际执行史。')
 add(1550,'mexico','修院、语言与原住民社会','跨洲传播','原住民信徒、方济各会、多明我会、奥斯定会','mexican-monasteries','十六世纪墨西哥的修院建筑和地方实践，呈现殖民统治下复杂的宗教互动。','十六世纪墨西哥及周边地区的修院和教堂，反映不同修会参与传教、教育与地方组织的过程。开放礼仪空间、建筑样式和城镇布局把欧洲规范与当地社会环境联系起来。','原住民工匠、翻译者、教理人员及地方群体并非只有被动接受的角色，他们在语言、图像与制度中作出选择。与此同时，征服、土地占用、劳役与宗教压制限制了这种选择，文化交流不能掩盖不平等。','1550年是十六世纪中叶的浏览落点，并非所有遗址的统一创建年。墨西哥城用于区域定位，所链波波卡特佩特火山周边修院群位于更广泛地区，不将全部建筑误标为首都中心的同一地点。',certainty='十六世纪区域过程 · 约年',label='十六世纪中叶 · 浏览落点1550年')
 # Keep chronological order even where independently authored related entries were added later.
 events.sort(key=lambda e:(e['year'],e['id']))
 data['events'].extend(events)
 data['editorial']='本图为史地阅读辅助。经文叙事、历史文献、后世传统与机构研究的证据性质不同；年份包括工作性近似年、约年与传统纪年，不是全部事件均有同等精度。地点为现代地理近似定位；叙事与文献联系线不是精确古道或实际行程复原，政治疆域也不表示信徒人口或教区界线。'
 data['sources'].append(dict(title='世界教会史：逐条来源与阅读说明',url='data/WORLD-CHURCH-SOURCES.md',usage='452—1648年自编中文纪事；标明原始文献、后世回顾与机构研究的不同性质。'))
 return data
